INSERT INTO `areatable_dbc` (`ID`, `ContinentID`, `ParentAreaID`, `AreaBit`, `Flags`, `SoundProviderPref`, `SoundProviderPrefUnderwater`, `AmbienceID`, `ZoneMusic`, `IntroSound`, `ExplorationLevel`, `AreaName_Lang_enUS`, `AreaName_Lang_enGB`, `AreaName_Lang_koKR`, `AreaName_Lang_frFR`, `AreaName_Lang_deDE`, `AreaName_Lang_enCN`, `AreaName_Lang_zhCN`, `AreaName_Lang_enTW`, `AreaName_Lang_zhTW`, `AreaName_Lang_esES`, `AreaName_Lang_esMX`, `AreaName_Lang_ruRU`, `AreaName_Lang_ptPT`, `AreaName_Lang_ptBR`, `AreaName_Lang_itIT`, `AreaName_Lang_Unk`, `AreaName_Lang_Mask`, `FactionGroupMask`, `LiquidTypeID_1`, `LiquidTypeID_2`, `LiquidTypeID_3`, `LiquidTypeID_4`, `MinElevation`, `Ambient_Multiplier`, `Lightid`) VALUES
(5102, 0, 40, 3826, 1073741888, 0, 0, 0, 0, 0, 10, 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 'Gartside Plot', 16712190, 0, 0, 0, 0, 0, -500.0, 0.0, 0);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(60858, 0, 0, 'Weird... but clever.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66434'),
(60858, 1, 0, 'Really? Goblins are insane.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66435'),
(60858, 2, 0, 'So it is possible...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66436'),
(60858, 3, 0, 'Get ready! I will now activate the golem! Draw its attention, and I will cast the Rewiring Spell. Don\'t damage it too much, it needs to remain intact!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66437'),
(60858, 4, 0, 'It worked!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66438'),
(60858, 5, 0, 'Maltimor Gartside looks into the blueprints.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66739'),
(3091, 100, 0, 'Franklin Hamar looks into the note.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66742'),
(3091, 101, 0, 'Awful handwriting, it\'s like the person writing this was blind. Alright, here it goes. Listen carefully.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66439'),
(3091, 102, 0, 'Tell G. that the people in Darkshire are getting delicious. Sorry, suspicious.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66440'),
(3091, 103, 0, 'The Night Watch is eyeing my shack every day. I need to move out soon if the production of runes is to continue.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66441'),
(3091, 104, 0, 'Send someone. Stormwind shall fall, yadda yadda, F.W. The end.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66442'),
(3091, 105, 0, 'Interesting note, friend. You and Hewen might be in trouble. But that\'s none of my business.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66443'),
(392, 100, 0, 'Cookie, I am sorry! I swear I will make it right. Farewell, my friend.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66423'),
(60709, 0, 0, 'Cookie looks at Grayson with sadness in his eyes and waves him off.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66421'),
(60709, 1, 0, 'Mrrgl?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66422');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030066, 'I... I should explain. Yes, I was lying to you all this time. I made the golems, with the help of Farad and some goblin machinery. We had lived here, in Moonbrook, many years ago.\n\nWe just wanted to escape this shithole. So we made the Harvest Golems, to help the farmers and, also, to get their money. But we knew that it was too expensive for an average farmer to buy one. So we were selling them for a low, low price. We were losing a lot of money on it.', 'I... I should explain. Yes, I was lying to you all this time. I made the golems, with the help of Farad and some goblin machinery. We had lived here, in Moonbrook, many years ago.\n\nWe just wanted to escape this shithole. So we made the Harvest Golems, to help the farmers and, also, to get their money. But we knew that it was too expensive for an average farmer to buy one. So we were selling them for a low, low price. We were losing a lot of money on it.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030066, 9030066);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030066, 0, 0, 'Listen more.', 0, 1, 1, 9030067, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030067, 'You probably already know where it is going. I\'m not proud of this part. There was a catch. When everyone\'s fields were protected by golems, we would activate their true nature.\n\nThey would become murderous machines. We would blame it on some vile warlock, or anyone else, it didn\'t matter. Only important thing was that we would be the only ones who could fix them, for a very high price.', 'You probably already know where it is going. I\'m not proud of this part. There was a catch. When everyone\'s fields were protected by golems, we would activate their true nature.\n\nThey would become murderous machines. We would blame it on some vile warlock, or anyone else, it didn\'t matter. Only important thing was that we would be the only ones who could fix them, for a very high price.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030067, 9030067);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030067, 0, 0, 'Listen more.', 0, 1, 1, 9030068, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030068, 'At least, that was the idea. In my greed, I activated the murderous killswitch when Farad was working with some golems in a workshop. I wanted him to die, so all the money would go to me.\n\nI learned later that he survived, and only got blinded. He hated me for it. But regardless, I saw the destruction I caused. I wanted to make the golems docile again… but our spell didn\'t work.', 'At least, that was the idea. In my greed, I activated the murderous killswitch when Farad was working with some golems in a workshop. I wanted him to die, so all the money would go to me.\n\nI learned later that he survived, and only got blinded. He hated me for it. But regardless, I saw the destruction I caused. I wanted to make the golems docile again… but our spell didn\'t work.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030068, 9030068);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030068, 0, 0, 'Listen more.', 0, 1, 1, 9030069, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030069, 'Some mistake we made during construction, or just lack of skill, I will never know. I couldn\'t fix them. Westfall became a wasteland. And then, came the Defias, with Farad on their side.\n\nAnd you know the rest of this story. You may judge me, think of me as a monster. The truth is, that you are probably right. I was a monster. But I did everything I could to fix it. And by the Light, I can only hope that it is enough.', 'Some mistake we made during construction, or just lack of skill, I will never know. I couldn\'t fix them. Westfall became a wasteland. And then, came the Defias, with Farad on their side.\n\nAnd you know the rest of this story. You may judge me, think of me as a monster. The truth is, that you are probably right. I was a monster. But I did everything I could to fix it. And by the Light, I can only hope that it is enough.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030069, 9030069);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (41162, 0, 0, '<Hand him the letter.>', 0, 1, 1, 9030066, 0, 0, 0, NULL, 0, 0);
