(15, 41162, 0, 0, 0, 2, 0, 60767, 1, 0, 0, 0, 0, '', 'mod-turtle-content: Maltimor - carries the letter');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030025, 'Of course it was him, the old fool. He thinks that my death will fix everything... Oh, how wrong he is. My death will change nothing!', 'Of course it was him, the old fool. He thinks that my death will fix everything... Oh, how wrong he is. My death will change nothing!', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030025, 9030025);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030025, 0, 0, '<Attack.>', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030024, 'Dammit. I knew they would find me. Alas, all good things come to an end. Before we fight for our lifes, tell me who sent you. Was it Maltimor?', 'Dammit. I knew they would find me. Alas, all good things come to an end. Before we fight for our lifes, tell me who sent you. Was it Maltimor?', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030024, 9030024);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030024, 0, 0, '<Stare silently.>', 0, 1, 1, 9030025, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9060854, 'Get out of my shack.', 'Get out of my shack.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9060854, 9060854);
