INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES (15, 9060854, 0, 0, 0, 47, 0, 40485, 8, 0, 0, 0, 0, '', 'mod-turtle-content gossip option');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030062, 'Well, where to begin? I traveled to Westfall and helped establish a church there. The locals were extremely friendly, religious folk themselves, and assisted in whatever manner they could. Me and them both brought the community together, created strong bonds and helped eachother when we were able.', 'Well, where to begin? I traveled to Westfall and helped establish a church there. The locals were extremely friendly, religious folk themselves, and assisted in whatever manner they could. Me and them both brought the community together, created strong bonds and helped eachother when we were able.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030062, 9030062);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030062, 0, 0, 'Listen more.', 0, 1, 1, 9030063, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030063, 'There was trouble though, between two families, the Molsen and Easton, a land dispute of sorts that dated back a generation, marriage problems between them, who owned what, and which property belonged to who.\n\nThe Molsens got it in their head that they would inherit the Easton estate, especially a young one, went by the name Carver, a ruffian of a lad, who got himself into all sorts of trouble.', 'There was trouble though, between two families, the Molsen and Easton, a land dispute of sorts that dated back a generation, marriage problems between them, who owned what, and which property belonged to who.\n\nThe Molsens got it in their head that they would inherit the Easton estate, especially a young one, went by the name Carver, a ruffian of a lad, who got himself into all sorts of trouble.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030063, 9030063);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030063, 0, 0, 'Listen more.', 0, 1, 1, 9030064, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030064, 'It was around this time that the thugs began to show up, the boy Carver was quick to join them. The Defias threatened families to leave their land with acts of violence and murder.\n\nSoon after the Easton family was murdered in cold blood, and many other families simply left, not wanting to face similar fates.', 'It was around this time that the thugs began to show up, the boy Carver was quick to join them. The Defias threatened families to leave their land with acts of violence and murder.\n\nSoon after the Easton family was murdered in cold blood, and many other families simply left, not wanting to face similar fates.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030064, 9030064);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030064, 0, 0, 'Listen more.', 0, 1, 1, 9030065, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030065, 'Less, and less showed up to my church, I had a small following, but the Defias made their presence known, threatened me to leave, and even beat me near death for refusing. I was stubborn, but not stubborn enough to die. So I left for Stormwind, where my tale continues now.', 'Less, and less showed up to my church, I had a small following, but the Defias made their presence known, threatened me to leave, and even beat me near death for refusing. I was stubborn, but not stubborn enough to die. So I left for Stormwind, where my tale continues now.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030065, 9030065);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9000952, 'Northshire Abbey sure is a nice, and quiet place.', 'Northshire Abbey sure is a nice, and quiet place.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9000952, 9000952);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9000952, 0, 0, 'So, what exactly happened in Westfall?', 0, 1, 1, 9030062, 0, 0, 0, NULL, 0, 0);
INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES (15, 9000952, 0, 0, 0, 47, 0, 40597, 8, 0, 0, 0, 0, '', 'mod-turtle-content gossip option');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030019, 'I took Cookie on the ship when he was very young, he was hostile and bitter at first but through that book, you\'ve found we had developed a bond. In a way Cookie was able to understand anyone without actually knowing a word they were saying.\n\nNot sure what to tell you matey, Cookie was my friend and I\'ve sent you to end him, which may be my greatest regret yet.', 'I took Cookie on the ship when he was very young, he was hostile and bitter at first but through that book, you\'ve found we had developed a bond. In a way Cookie was able to understand anyone without actually knowing a word they were saying.\n\nNot sure what to tell you matey, Cookie was my friend and I\'ve sent you to end him, which may be my greatest regret yet.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030019, 9030019);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9000392, 'Do not be alarmed, $r. I have long since passed from this land but I intend no harm to your kind. I have witnessed too much death in my time. My only wish now is for peace. Perhaps you can help my cause.', 'Do not be alarmed, $r. I have long since passed from this land but I intend no harm to your kind. I have witnessed too much death in my time. My only wish now is for peace. Perhaps you can help my cause.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9000392, 9000392);
